import { use } from 'react'
import { IoCloseSharp } from 'react-icons/io5'

import {
  Box,
  Card,
  CardActions,
  CardContent,
  CardHeader,
  Fade,
  IconButton,
  Modal,
} from '@mui/material'

import ConceptModalContext from '@/contexts/panels/concepts/modal/ConceptModalContext'
import ConceptModalDataContext from '@/contexts/panels/concepts/modal/ConceptModalDataContext'
import ConceptModalProcessingContext from '@/contexts/panels/concepts/modal/ConceptModalProcessingContext'
import ProcessingMsg from '@/components/common/ProcessingMessage'

const ConceptModal = () => {
  const { closeModal } = use(ConceptModalContext)
  const { modal } = use(ConceptModalDataContext)
  const { processing, processingMessage } = use(ConceptModalProcessingContext)

  if (!modal) {
    return null
  }

  const { actions, content, title, minWidth = 500, maxWidth, focusClose = false, contentSx } = modal

  const isProcessing = Boolean(processing)
  const renderModalSlot = slot => (typeof slot === 'function' ? slot() : slot)

  return (
    <Modal
      aria-labelledby='modal-alert'
      aria-describedby='modal-alert-description'
      open
      closeAfterTransition
    >
      <Fade in={true} timeout={500}>
        <Box
          sx={{
            alignItems: 'center',
            display: 'flex',
            justifyContent: 'center',
            mt: 10,
          }}
        >
          <Card sx={{ p: 1, pb: 0, position: 'relative', minWidth, maxWidth }}>
            <IconButton
              autoFocus={focusClose}
              aria-label='close'
              onClick={() => closeModal(false)}
              sx={{ position: 'absolute', right: 8, top: 8 }}
              disabled={isProcessing}
            >
              <IoCloseSharp />
            </IconButton>
            <CardHeader title={renderModalSlot(title)} />
            <CardContent sx={[{ pb: 0, pt: 0, position: 'relative' }, contentSx]}>
              {renderModalSlot(content)}
            </CardContent>
            {actions && (
              <CardActions style={{ display: 'flex', justifyContent: 'center' }}>
                {renderModalSlot(actions)}
              </CardActions>
            )}
            {isProcessing && <ProcessingMsg message={processingMessage} />}
          </Card>
        </Box>
      </Fade>
    </Modal>
  )
}

export default ConceptModal
